function [f0_est, magn0_est] = extract_fundamental_of_sin(t, i1, plot_results)
%CREATEFIT1(T,I1)
%  Create a fit.
%
%  Data for 'i1' fit:
%      X Input: t
%      Y Output: i1
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 27-Jun-2023 11:34:20


%% Fit: 'i1'.
[xData, yData] = prepareCurveData( t, i1 );

% Set up fittype and options.
ft = fittype( 'sin1' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
opts.Lower = [-Inf 0 -Inf];
opts.StartPoint = []; %0 317.543838802123 0];

% Fit model to data.
[fitresult, ~] = fit( xData, yData, ft, opts );

f0_est      = fitresult.b1/2/pi;
magn0_est   = fitresult.a1;


if(exist('plot_results','var'))

    % Plot fit with data.
    figure( 'Name', 'i1' );
    h = plot( fitresult, xData, yData );
    legend( h, 'i1 vs. t', 'i1', 'Location', 'NorthEast', 'Interpreter', 'none' );
    % Label axes
    xlabel( 't', 'Interpreter', 'none' );
    ylabel( 'i1', 'Interpreter', 'none' );
    grid on



end
